/// <summary>
/// Represents a despatch advice event for a sales order.
/// Task 355193: PB168 - E2E - SO ASN to Ampol - D365
/// </summary>
[BusinessEvents(classStr(METDespatchAdviceEventContract),
    "@MET:DispatchAdviceEvent",
    "@MET:SOASNEventHelp",
    ModuleAxapta::AccountsReceivable)]
public class METDespatchAdviceEvent extends BusinessEventsBase
{
    private DataAreaId          dataAreaId;
    private SalesId             salesId;
    private METEDISenderCode    senderCode;
    private WMSPickingRouteID   wmsPicklistNumber;

}

Method.Source:
/// <summary>
/// Creates a new instance of the METDespatchAdviceEvent class.
/// </summary>
/// <param name = "_dataAreaId">Data area ID.</param>
/// <param name = "_salesId">Sales ID.</param>
/// <param name = "_senderCodeId">SenderId</param>
/// <param name = "_wmsPicklistNumber">WMS picklist number.</param>
/// <returns></returns>
public static METDespatchAdviceEvent newFromSalesOrder(
    DataAreaId          _dataAreaId,
    SalesId             _salesId,
    METEDISenderCode    _senderCodeId,
    WMSPickingRouteID   _wmsPicklistNumber)
{
    METDespatchAdviceEvent event = new METDespatchAdviceEvent();
    event.parmDataAreaId(_dataAreaId);
    event.parmSalesId(_salesId);
    event.parmSenderCode(_senderCodeId);
    event.parmWMSPicklistNumber(_wmsPicklistNumber);

    return event;
}

/// <summary>
/// Sets the data area ID.
/// </summary>
/// <param name = "_dataAreaId">Data area ID.</param>
/// <returns>Data area ID.</returns>
public DataAreaId parmDataAreaId(DataAreaId _dataAreaId = dataAreaId)
{
    dataAreaId = _dataAreaId;
    return dataAreaId;
}

/// <summary>
/// Sets the sales ID.
/// </summary>
/// <param name = "_salesId">Sales ID.</param>
/// <returns>Sales ID.</returns>
public SalesId parmSalesId(SalesId _salesId = salesId)
{
    salesId = _salesId;
    return salesId;
}

/// <summary>
/// Sets the SenderCode ID.
/// </summary>
/// <param name = "_senderCodeId">SenderId</param>
/// <returns>SenderId</returns>
public METEDISenderCode parmSenderCode(METEDISenderCode _senderCodeId = senderCode)
{
    senderCode = _senderCodeId;
    return senderCode;
}

/// <summary>
/// Sets the WMS picklist number.
/// </summary>
/// <param name = "_wmsPicklistNumber">WMS picklist number.</param>
/// <returns>WMS picklist number.</returns>
public WMSPickingRouteID parmWMSPicklistNumber(WMSPickingRouteID _wmsPicklistNumber = wmsPicklistNumber)
{
    wmsPicklistNumber = _wmsPicklistNumber;
    return wmsPicklistNumber;
}

/// <summary>
/// Builds the event contract for the despatch advice event.
/// </summary>
/// <returns>The event contract.</returns>
[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    return METDespatchAdviceEventContract::newFromSalesOrder(
        dataAreaId,
        salesId,
        senderCode,
        wmsPicklistNumber);
}
